import { MakeLogicType, kea, key, path, props } from 'kea'
import { loaders } from 'kea-loaders'

import { ApiConfig } from 'lib/api'

import { aiObservabilityTracesClustersRetrieve } from '../../generated/api'
import type { TraceClusterApi } from '../../generated/api.schemas'
import { encodeTraceIdSegment } from './traceIdSegment'

export interface TraceClustersLogicProps {
    traceId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceClustersLogicValues {
    clusters: TraceClusterApi[] | null
    clustersLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceClustersLogicActions {
    loadClusters: (createdAt: string) => string
    loadClustersFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadClustersSuccess: (
        clusters: TraceClusterApi[],
        payload?: string
    ) => {
        clusters: TraceClusterApi[]
        payload?: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceClustersLogicMeta {
    key: string
}

export type traceClustersLogicType = MakeLogicType<
    traceClustersLogicValues,
    traceClustersLogicActions,
    TraceClustersLogicProps,
    traceClustersLogicMeta
>

export const traceClustersLogic = kea<traceClustersLogicType>([
    props({} as TraceClustersLogicProps),
    key((props) => props.traceId),
    path((key) => ['products', 'ai_observability', 'frontend', 'redesign', 'trace', 'traceClustersLogic', key]),
    loaders(({ props }) => ({
        clusters: [
            null as TraceClusterApi[] | null,
            {
                // The read is bounded by the trace's start, so it waits for the trace instead of starting on mount.
                loadClusters: async (createdAt: string): Promise<TraceClusterApi[]> => {
                    const { clusters } = await aiObservabilityTracesClustersRetrieve(
                        String(ApiConfig.getCurrentProjectId()),
                        encodeTraceIdSegment(props.traceId),
                        { created_at: createdAt }
                    )
                    return clusters
                },
            },
        ],
    })),
])
